fn solve(a: i8, b: i8, k: i8) -> (i8, i8) {
    // First, remove as many as we can from pile `a`, up to k
    let removed_from_a = a.min(k);
    let remaining_removals = k - removed_from_a;
    let new_a = a - removed_from_a;

    // Then, with any removals left, remove from pile `b`
    let removed_from_b = b.min(remaining_removals);
    let new_b = b - removed_from_b;

    (new_a, new_b)
}

